 {Shadow lab(argv[1],verts);std::cout<<"validation_enabled="<<lab.validation<<"\n";if(!lab.validation)throw std::runtime_error("validation required");auto pixels=lab.draw(std::vector<float>(3185,0),{0,0,0,1},{mode=="bypass"?1.f:0.f,0,0,0});const char* names[]={"color","velocity","id"};for(int i=0;i<3;i++)save(out/(std::string(names[i])+".f32"),pixels[i]);std::vector<float>d(3185);memcpy(d.data(),lab.buffers[lab.readDepth].map,3185*4);save(out/"depth.f32",d);lab.readShadow();memcpy(d.data(),lab.buffers[lab.readMap].map,3185*4);save(out/"shadow.f32",d);}if(validationErrors)throw std::runtime_error("validation failed");return 0;
